            if subsequence[left] != subsequence[right] {
                // print("isPlaindrome false for subsequence = \(subsequence)")
                return false }
            left = subsequence.index(after: left)
            right = subsequence.index(before: right)
        }
        // print("isPlaindrome true for subsequence = \(subsequence)")
        return true
    }
}
